"""EXP-DISTR-001 Experience distributor API contract extension."""
def extend_experience(spec):
    from authorization import object_schema, operation, parameter, UUID, VERSION, REF
    m=spec['components']['schemas'];p=spec['paths']
    nullable=lambda value:{'anyOf':[value,{'type':'null'}]}
    m['DistributorApplication']=object_schema({'id':UUID,'state':{'enum':['SUBMITTED','UNDER_REVIEW','ACTIVATION_PENDING','APPROVED','REJECTED','SUSPENSION_PENDING','SUSPENDED']},'organizationId':nullable(UUID),'submittedAt':{'type':'string','format':'date-time'},'version':VERSION})
    m['DistributorDocumentInput']={'type':'array','minItems':1,'maxItems':20,'uniqueItems':True,'items':UUID}
    m['DistributorApplicationInput']=object_schema({'organizationName':{'type':'string','minLength':1,'maxLength':200},'countryCode':{'type':'string','const':'NG'},'businessReference':{'type':'string','maxLength':100},'documentIds':REF('DistributorDocumentInput')});m['DistributorApplicationInput']['required']=['organizationName','countryCode','documentIds']
    m['DistributorApplicationPage']=object_schema({'content':{'type':'array','maxItems':100,'items':REF('DistributorApplication')},'page':{'type':'integer','minimum':0},'size':{'type':'integer','minimum':1,'maximum':100},'totalElements':{'type':'integer','format':'int64','minimum':0},'totalPages':{'type':'integer','format':'int64','minimum':0},'sort':{'type':'string'}})
    m['DistributorReviewInput']=object_schema({'reason':{'type':'string','minLength':1,'maxLength':500},'documentsVerified':{'type':'boolean'}})
    m['DistributorDecisionInput']=object_schema({'decision':{'enum':['APPROVE','REJECT','SUSPEND']},'reason':{'type':'string','minLength':1,'maxLength':500},'marketId':UUID,'priceBookId':UUID});m['DistributorDecisionInput']['required']=['decision','reason']
    m['DistributorApplicationDetail']=object_schema({'id':UUID,'organizationName':{'type':'string','maxLength':200},'countryCode':{'type':'string','const':'NG'},'businessReference':nullable({'type':'string','maxLength':100}),'state':{'enum':['SUBMITTED','UNDER_REVIEW','ACTIVATION_PENDING','APPROVED','REJECTED','SUSPENSION_PENDING','SUSPENDED']},'documents':{'type':'array','maxItems':20,'items':object_schema({'fileId':UUID,'documentType':{'type':'string','maxLength':40},'scanStatus':{'enum':['UPLOADING','QUARANTINED','CLEAN','REJECTED']}})},'reviewerPartyId':nullable(UUID),'reviewReason':nullable({'type':'string','maxLength':500}),'organizationId':nullable(UUID),'version':VERSION})
    key=parameter('Idempotency-Key','header',{'type':'string','minLength':1,'maxLength':100},True);match=parameter('If-Match','header',{'type':'string','pattern':'^"(0|[1-9][0-9]{0,18})"$'},True);ident=parameter('id','path',UUID,True)
    def add(api,method,path,response,desc,params=(),body=None,status=200,scope=None):
        op=operation(api,desc,response,list(params));op['responses'][str(status)]=op['responses'].pop('200');op['responses'][str(status)].setdefault('headers',{})['Cache-Control']={'schema':{'const':'no-store'}}
        if body:op['requestBody']={'required':True,'content':{'application/json':{'schema':REF(body)}}}
        if scope:op['security']=[{'workload':[scope],'signedActor':[]}]
        p.setdefault(path,{})[method.lower()]=op
    add('API-092','POST','/api/v1/distributor-applications','DistributorApplication','Signed current CUSTOMER; idempotent create. Only applicant-owned CLEAN PRIVATE unlinked files are accepted. Required document types and recipient group must be explicitly configured; missing configuration fails closed. EVT-019 is written in the same Experience transaction.',[key],'DistributorApplicationInput',201,'distributor.create_WITH_SIGNED_CUSTOMER')
    add('API-093','GET','/api/v1/me/distributor-applications','DistributorApplication','Signed current CUSTOMER; own applications only, no cross-owner lookup.',(),None,200,'distributor.read_WITH_SIGNED_CUSTOMER')
    p['/api/v1/me/distributor-applications']['get']['responses']['200']['content']['application/json']['schema']={'type':'array','maxItems':100,'items':REF('DistributorApplication')}
    add('API-094','GET','/api/v1/staff/distributor-applications','DistributorApplicationPage','Signed SALES actor only; bounded page and deterministic sort.',[parameter('state','query',{'enum':['SUBMITTED','UNDER_REVIEW','ACTIVATION_PENDING','APPROVED','REJECTED','SUSPENSION_PENDING','SUSPENDED']}),parameter('page','query',{'type':'integer','minimum':0,'default':0}),parameter('size','query',{'type':'integer','minimum':1,'maximum':100,'default':20}),parameter('sort','query',{'enum':['submittedAt,asc','submittedAt,desc'],'default':'submittedAt,desc'})],None,200,'distributor.queue_WITH_SIGNED_ACTOR')
    add('API-177','GET','/api/v1/staff/distributor-applications/{id}','DistributorApplicationDetail','Signed SALES actor only. No document bytes; protected-file access is a separate authorized operation.',[ident],None,200,'distributor.detail_WITH_SIGNED_ACTOR')
    add('API-172','POST','/api/v1/staff/distributor-applications/{id}/review','DistributorApplication','Signed SALES actor. Requires applicant-owned CLEAN private proofs, If-Match, verified document review and records the reviewer.',[ident,match,key],'DistributorReviewInput',200,'distributor.review_WITH_SIGNED_ACTOR')
    add('API-095','POST','/api/v1/staff/distributor-applications/{id}/decision','DistributorApplication','Signed SALES actor. Persists a decision command and EVT-020 before API-117. Approval requires a prior distinct reviewer. Commerce entitlement is represented only after exact command acknowledgment.',[ident,match,key],'DistributorDecisionInput',202,'distributor.decision_WITH_SIGNED_ACTOR')
    for path,method in [('/api/v1/distributor-applications','post'),('/api/v1/staff/distributor-applications/{id}/review','post'),('/api/v1/staff/distributor-applications/{id}/decision','post')]:
        p[path][method]['responses']['412']={'description':'Resource version changed; reload and retry with the current ETag.'}
    spec['components']['securitySchemes']['signedActor']={'type':'apiKey','in':'header','name':'X-Nigson-Actor'}
    spec['components']['securitySchemes']['workload']['flows']['clientCredentials']['scopes'].update({s:'Exact distributor API with a signed Commerce actor; Experience verifies SALES or CUSTOMER role' for s in ['distributor.create_WITH_SIGNED_CUSTOMER','distributor.read_WITH_SIGNED_CUSTOMER','distributor.queue_WITH_SIGNED_ACTOR','distributor.detail_WITH_SIGNED_ACTOR','distributor.review_WITH_SIGNED_ACTOR','distributor.decision_WITH_SIGNED_ACTOR']})
    return spec
